llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, the closest analogue (Morgan 0.3182) and a sulfonamide diuretic sharing the sulfamoyl chlorophenyl motif, has approximately 100% absolute oral bioavailability in humans, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hydrochlorothiazide, a thiazide sulfonamide diuretic with the same sulfamoyl chlorophenyl substructure, has absolute oral bioavailability of 66–75% in healthy adults, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Bumetanide, a sulfonamide loop diuretic with a sulfamoyl chlorophenyl group, showed oral bioavailability of 0.664 ± 0.112 versus intravenous dosing in healthy subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a sulfonamide diuretic with a similar sulfamoyl chlorophenyl core, has low oral bioavailability (10–19%) in humans attributed to first-pass metabolism; this is contradictory evidence, but its lower transferability and the preponderance of high-F analogues limit its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a chlorthalidone-like sulfamoyl chlorophenyl isoindolinone. The closest and class-related analogues (metolazone, hydrochlorothiazide, bumetanide) consistently show high human oral bioavailability (66–100%), while the only clearly low-F analogue (azosemide) is less transferable and represents a first-pass-metabolism outlier. The physicochemical prior is favorable for absorption. Therefore F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability study for the query molecule itself.",
    "Azosemide demonstrates that sulfonamide diuretics can occasionally have low F due to first-pass metabolism; the metabolic stability/first-pass extraction of the isoindolinone core is not directly measured in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

